fn get_triple(a: &[i32]) -> usize {
    let n = a.len();
    // If there are fewer than 3 elements, no triple can exist.
    if n < 3 {
        return n;
    }
    // Scan for any i such that a[i] == a[i+1] == a[i+2].
    for i in 0..(n - 2) {
        if a[i] == a[i + 1] && a[i + 1] == a[i + 2] {
            return i;
        }
    }
    // If we find no triple, return the slice length.
    n
}

